    stride_out_c_i64 = tl.full((), stride_out_c, tl.int64)
    stride_out_d_i64 = tl.full((), stride_out_d, tl.int64)
    stride_out_h_i64 = tl.full((), stride_out_h, tl.int64)
    stride_out_w_i64 = tl.full((), stride_out_w, tl.int64)

